11 /// Parse "<n><unit>" groups, unit in {s, m, h}, e.g. "2h30m".
12 pub fn parse_duration(text: &str) -> Result<Duration, ParseError> {
13     if text.is_empty() {
14         return Err(ParseError::Empty);
15     }
16     let mut total = 0u64;
17     let mut digits = String::new();
18     for ch in text.chars() {
